 "content": "from collections import Counter


def _infer_period(grid):
    h, w = len(grid), len(grid[0])
    best = None
    for period in range(2, 10):
        bins = [Counter() for _ in range(period)]
        for r in range(3, h):
            for c in range(3, w):
                value = grid[r][c]
                if value not in (0, 4):
                    bins[(r + c) % period][value] += 1
        score = sum(max(b.values(), default=0) for b in bins)
        total = sum(sum(b.values()) for b in bins)
        # Prefer the shortest period in a tie.
        key = (score / total if total else 0, -period)
        if best is None or key > best[0]:
            best = (key, period, [b.most_common(1)[0][0] if b else 0 for b in bins])
    return best[1], best[2]


def transform(grid):
    out = [row[:] for row in grid]
    period, colors = _infer_period(grid)
    for r, row in enumerate(out):
        for c, value in enumerate(row):
            if value != 0:
                continue
            if r < 2 or c < 2:
                out[r][c] = 1
            elif r == 2 or c == 2:
                out[r][c] = 4
            else:
                out[r][c] = colors[(r + c) % period]
    return out
