def _row_model(row):
    # Repeating color runs are horizontal; blacked-out cells are erased portions.
    # Infer the cycle per row from its surviving patterned cells, ignoring frame.
    best = None
    for period in range(2, 10):
        bins = [Counter() for _ in range(period)]
        for c in range(3, len(row)):
            value = row[c]
            if value not in (0, 4):
                bins[c % period][value] += 1
        score = sum(max(b.values(), default=0) for b in bins)
        total = sum(sum(b.values()) for b in bins)
        key = (score / total if total else 0, -period)
        if best is None or key > best[0]:
            best = (key, period, [b.most_common(1)[0][0] if b else None for b in bins])
    return best[1], best[2]


def transform(grid):
    out = [row[:] for row in grid]
    for r, row in enumerate(grid):
        period, colors = _row_model(row)
        for c, value in enumerate(row):
            if value != 0:
                continue
            if r < 2 or c < 2:
                out[r][c] = 1
            elif r == 2 or c == 2:
                out[r][c] = 4
            else:
                replacement = colors[c % period]
                if replacement is None:
                    # A row fully occluded in this residue is reconstructed from
                    # the nearest visible value in the same row.
                    replacement = next((row[j] for distance in range(1, len(row))
                                        for j in (c-distance, c+distance)
                                        if 3 <= j < len(row) and row[j] not in (0, 4)), 1)
                out[r][c] = replacement
    return out
